(()=>{const bar=document.querySelector('#globalGenerationStatus');if(!bar)return;const group=document.createElement('div');group.id='statusMemoryControls';group.style.cssText='display:flex;gap:12px;align-items:center;margin-left:auto;flex:none;font-size:13px';const label=document.createElement('span');label.textContent='内存读取中…';label.style.whiteSpace='nowrap';const button=document.createElement('button');button.textContent='清理内存';button.disabled=true;button.style.cssText='padding:5px 10px;white-space:nowrap;font-size:12px;color:#b5e3d2;background:#1b302a;border:1px solid #46665c';group.append(label,button);bar.append(group);let cleaning=false,reading=false;const port=()=>Number(localStorage.getItem('frame-comfy-port')||8188);async function refresh(){if(reading)return;reading=true;try{const r=await fetch('/api/memory?port='+port(),{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error();const m=await r.json();label.textContent='内存 '+m.used_gb.toFixed(1)+' / '+m.total_gb.toFixed(1)+' GB';label.title='系统物理内存占用 '+m.percent+'%';button.disabled=cleaning||!m.can_clean;button.title=!m.connected?'ComfyUI未连接':m.can_clean?'卸载模型并释放缓存，下次生成会重新加载':'生成或排队中，暂不能清理';}catch{label.textContent='内存状态暂不可用';button.disabled=true;}finally{reading=false;}}button.onclick=async()=>{if(cleaning)return;cleaning=true;button.disabled=true;button.textContent='正在清理…';try{const r=await fetch('/api/memory/clean?port='+port(),{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),result=await r.json();if(!r.ok)throw Error(result.error||'清理失败');if(typeof toast==='function')toast(result.message);setTimeout(refresh,2000);setTimeout(refresh,6000);}catch(e){if(typeof toast==='function')toast(e.message);}finally{cleaning=false;button.textContent='清理内存';refresh();}};refresh();setInterval(refresh,5000);})();
(()=>{const bar=document.querySelector('#globalGenerationStatus');if(!bar)return;const group=document.createElement('div');group.style.cssText='display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:13px';const label=document.createElement('span'),button=document.createElement('button');button.textContent='启动 ComfyUI';button.style.cssText='padding:5px 10px;white-space:nowrap;font-size:12px;color:#b5e3d2;background:#1b302a;border:1px solid #46665c';group.append(label,button);bar.insertBefore(group,document.querySelector('#statusMemoryControls'));let busy=false,checking=false;const port=()=>Number(localStorage.getItem('frame-comfy-port')||8188);function show(s){const online=s.status==='running',starting=s.status==='starting';label.textContent=online?'ComfyUI 已连接':starting?'ComfyUI 正在启动…':s.error||'ComfyUI 未启动';label.style.color=online?'#b5e3d2':'#d7b77a';button.hidden=online;button.disabled=busy||starting;button.textContent=starting?'正在启动…':'启动 ComfyUI';}async function refresh(){if(checking||busy)return;checking=true;try{const r=await fetch('/api/tools/comfy/status?port='+port(),{cache:'no-store',signal:AbortSignal.timeout(6000)});if(!r.ok)throw Error();show(await r.json());}catch{label.textContent='ComfyUI 状态读取失败';button.hidden=false;button.disabled=false;}finally{checking=false;}}button.onclick=async()=>{if(busy)return;busy=true;button.disabled=true;button.textContent='正在启动…';try{const r=await fetch('/api/tools/comfy/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({port:port()})}),s=await r.json();if(!r.ok)throw Error(s.error||'启动失败');busy=false;show(s);}catch(e){busy=false;button.disabled=false;button.textContent='重试启动';label.textContent=e.message;}};refresh();setInterval(refresh,3000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});})();
(()=>{const bar=document.querySelector('#globalGenerationStatus');if(!bar)return;const button=document.createElement('button');button.id='forceStopComfy';button.textContent='强制停止';button.title='结束 ComfyUI 进程，终止该服务当前全部任务';button.style.cssText='padding:5px 10px;white-space:nowrap;font-size:12px;color:#f2b5ad;background:#38252a;border:1px solid #88594f';bar.append(button);let stopping=false;button.onclick=async()=>{if(stopping||!confirm('强制停止将结束 ComfyUI，终止当前全部生成任务。已保存的图片和视频会保留。确定继续？'))return;stopping=true;button.disabled=true;button.textContent='正在强制停止…';try{const r=await fetch('/api/comfy-force-stop',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({port:Number(localStorage.getItem('frame-comfy-port')||8188),confirm:true})}),j=await r.json();if(!r.ok)throw Error(j.error||'强制停止失败');button.textContent='已强制停止';if(typeof toast==='function')toast(j.message);setTimeout(()=>location.reload(),1000);}catch(e){button.textContent='重试强制停止';if(typeof toast==='function')toast(e.message);else alert(e.message);}finally{stopping=false;button.disabled=false;}};})();